//! Table and column markers together with their relational contracts.

use crate::dialect::Dialect;
use crate::schema::alias::{AliasedCol, TableAlias};

/// A table of the database schema, represented as a zero-sized marker type.
///
/// Implementations are usually generated by the [`table!`](crate::table) macro.
pub trait Table {
    /// The SQL identifier of the table, known at compile time.
    const NAME: &'static str;

    /// The `FROM` / `JOIN` reference of this table, alias included.
    ///
    /// The default reference is the bare table name; [`Aliased`](crate::schema::Aliased)
    /// tables override it to render their `AS` clause.
    fn table_ref() -> TableRef {
        TableRef::plain(Self::NAME)
    }

    /// Builds the expression node referencing `column` of this table.
    ///
    /// The default carries the SQL name of the table, which lets the renderer
    /// qualify the reference whenever the statement spans several relations;
    /// tables referenced under an alias override it to carry their alias, so
    /// joins over repeated table references stay unambiguous.
    fn column_expr(column: &'static str) -> crate::expr::ExprKind {
        crate::expr::ExprKind::Column {
            table: Self::NAME,
            name: column,
        }
    }
}

/// A table reference rendered into a `FROM` or `JOIN` clause.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct TableRef {
    /// The SQL identifier of the table.
    pub name: &'static str,

    /// The optional alias the table is referenced by.
    pub alias: Option<&'static str>,
}

impl TableRef {
    /// Creates a reference to a table without an alias.
    pub const fn plain(name: &'static str) -> Self {
        Self { name, alias: None }
    }

    /// Creates a reference to `name` exposed under `alias`.
    pub const fn aliased(name: &'static str, alias: &'static str) -> Self {
        Self {
            name,
            alias: Some(alias),
        }
    }

    /// Renders the reference, appending `AS "alias"` when the table is aliased.
    pub fn render<D: Dialect>(&self, out: &mut String) {
        D::push_quoted_identifier(out, self.name);
        if let Some(alias) = self.alias {
            out.push_str(" AS ");
            D::push_quoted_identifier(out, alias);
        }
    }
}

/// A column of a database [`Table`], represented as a zero-sized marker type.
pub trait Column {
    /// The table this column belongs to.
    type Table: Table;

    /// The Rust type used to represent this column's values.
    type RustType;

    /// The SQL identifier of the column, known at compile time.
    const NAME: &'static str;

    /// Builds the expression node referencing this column.
    ///
    /// The node carries the [`Table::NAME`] of [`Column::Table`], so the renderer
    /// qualifies the reference whenever a bare name would be ambiguous or
    /// unresolvable; columns of an [`Aliased`](crate::schema::Aliased) table
    /// override it to reference their alias directly.
    fn expr_kind() -> crate::expr::ExprKind {
        crate::expr::ExprKind::Column {
            table: <Self::Table as Table>::NAME,
            name: Self::NAME,
        }
    }

    /// Addresses this column through the table alias `A`.
    ///
    /// Column markers are zero-sized values, so the method only fixes the alias
    /// the column is referenced by and returns the matching [`AliasedCol`]
    /// marker without any turbofish-heavy construction:
    ///
    /// ```
    /// use rurqe_core::schema::{AliasedCol, Column, TableAlias};
    ///
    /// rurqe_core::table! {
    ///     User => "users" {
    ///         UserId => "id": i64,
    ///     }
    /// }
    ///
    /// rurqe_core::table_alias! {
    ///     /// The `u` alias.
    ///     U1 => "u"
    /// }
    ///
    /// let through_column: AliasedCol<U1, UserId> = UserId.alias::<U1>();
    /// let through_alias: AliasedCol<U1, UserId> = U1.col(UserId);
    /// ```
    fn alias<A: TableAlias>(self) -> AliasedCol<A, Self>
    where
        Self: Sized,
    {
        AliasedCol::new()
    }
}

/// Statically asserts that a [`Column`] belongs to the table `T`.
///
/// The trait is satisfied exactly for the table declared as
/// [`Column::Table`], so using a column with a foreign table fails to compile
/// with a short, actionable diagnostic.
#[diagnostic::on_unimplemented(
    message = "column `{Self}` does not belong to table `{T}`",
    label = "column `{Self}` cannot be used where a column of `{T}` is required",
    note = "a column may only be used with the table declared by its `Column::Table` associated type"
)]
pub trait ColumnBelongsTo<T: Table> {}

impl<C: Column> ColumnBelongsTo<C::Table> for C {}

/// Declares a table marker type together with its column marker types.
///
/// Each column links back to the table through [`Column::Table`] and carries its
/// Rust value type through [`Column::RustType`]:
///
/// ```
/// rurqe_core::table! {
///     /// The `users` table.
///     User => "users" {
///         UserId => "id": i64,
///         UserEmail => "email": String,
///     }
/// }
///
/// use rurqe_core::schema::{Column, Table};
///
/// assert_eq!(User::NAME, "users");
/// assert_eq!(UserEmail::NAME, "email");
/// assert_eq!(<<UserEmail as Column>::Table as Table>::NAME, "users");
/// ```
///
/// The declaration occupies both namespaces, which is what gives a column two
/// equivalent spellings. The type namespace carries the table marker together
/// with one field per column, so `User.UserId` addresses the `id` column through
/// the table it belongs to; the value namespace carries a zero-sized `User`
/// value of that type, so a builder receives the very same table. Neither
/// spelling needs a turbofish, and the qualified address costs nothing:
///
/// ```
/// rurqe_core::table! {
///     /// The `users` table.
///     User => "users" {
///         UserId => "id": i64,
///         UserEmail => "email": String,
///     }
/// }
///
/// // `User` is a value, so it is handed to a builder directly.
/// use rurqe_core::schema::Table;
///
/// // `User` is a value, so it is handed to a builder directly.
/// assert_eq!(User::NAME, "users");
///
/// // The qualified address reaches the same marker the bare type names, which
/// // keeps the prefix optional.
/// assert_eq!(User.UserId, UserId);
/// assert_eq!(User.UserEmail, UserEmail);
///
/// // The accessor carries markers only, so it stays zero-sized.
/// assert_eq!(core::mem::size_of::<User>(), 0);
/// ```
#[macro_export]
macro_rules! table {
    (
        $(#[$table_meta:meta])*
        $table:ident => $table_name:literal {
            $(
                $(#[$column_meta:meta])*
                $column:ident => $column_name:literal : $rust_type:ty,
            )*
        }
    ) => {
        $(#[$table_meta])*
        #[allow(dead_code, non_snake_case)]
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
        pub struct $table {
            $(
                $(#[$column_meta])*
                #[allow(non_snake_case)]
                pub $column: $column,
            )*
        }

        #[allow(dead_code, non_upper_case_globals)]
        pub const $table: $table = $table {
            $($column: $column,)*
        };

        impl $crate::schema::Table for $table {
            const NAME: &'static str = $table_name;
        }

        $(
            $(#[$column_meta])*
            #[allow(dead_code)]
            #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
            pub struct $column;

            impl $crate::schema::Column for $column {
                type Table = $table;
                type RustType = $rust_type;

                const NAME: &'static str = $column_name;
            }

            $crate::__rurqe_column_arithmetic!([] [] $column, $table);
        )*

        /// Exports the columns this table declares to the declaration that
        /// mirrors them, so an alias of the table restates no column list.
        ///
        /// The expansion names every column of the table in declaration order
        /// as a `(marker, SQL name)` pair, which is the whole input an alias
        /// accessor needs.
        #[doc(hidden)]
        #[allow(unused_macros)]
        macro_rules! $table {
            () => {
                [$(( $column, $column_name )),*]
            };
        }
    };
}
